package it.frociart.app;
import java.nio.file.*;import java.nio.charset.*;import java.util.*;import static it.frociart.app.FlowModel.*;
public final class OutputContinuationTests {
 static int checks;static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}static String text(Path p)throws Exception{return new String(Files.readAllBytes(p),StandardCharsets.UTF_8);}
 static FlowEngine.Runner run(Document d,String[] inputs){FlowEngine.Runner r=new FlowEngine.Runner(d);int at=0;for(int i=0;i<10000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++){if(r.state==FlowEngine.State.WAITING)r.submitInput(inputs[at++]);else r.step();}check(r.state==FlowEngine.State.COMPLETED,"Execution completes: "+r.errorMessage);return r;}
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]),out=root.resolve("android");Files.createDirectories(out);for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String[] row=line.split("\t",-1);String expected=FlowEngine.evaluate(row[1],null).format();String[] inputs=row[3].isEmpty()?new String[0]:row[3].split("\\|");Document d=FlowPseudocode.decode(text(root.resolve("fixtures/"+row[0]+".pseudo")));FlowEngine.Runner r=run(d,inputs);check(r.outputText().equals(expected),"Visible text "+row[0]);check(r.output.size()==r.outputNewlines.size(),"Flags complete");StringBuilder stream=new StringBuilder();for(int i=0;i<r.output.size();i++)stream.append(r.output.get(i)).append(r.outputNewlines.get(i)?"\n":"");check(stream.toString().equals(FlowEngine.evaluate(row[2],null).format()),"Exact output stream");check(r.outputText()==r.outputText(),"Cached reads");check(run(d.copy(),inputs).outputText().equals(expected),"Clone");check(run(FlowPseudocode.decode(FlowPseudocode.encode(d)),inputs).outputText().equals(expected),"Pseudocode");String encoded=FlowCodec.encode(d);Files.write(out.resolve(row[0]+".frociart"),encoded.getBytes(StandardCharsets.UTF_8));check(run(FlowCodec.decode(encoded),inputs).outputText().equals(expected),"File round trip");check(run(FlowCodec.decode(text(root.resolve("pc/"+row[0]+".frociart"))),inputs).outputText().equals(expected),"PC project exchange");FlowSource.Program source=FlowSource.compile(d);String py=FlowPython.generate(source,text(root.resolve("../frociart-v1-capabilities/pc/Source/PythonRuntime.py"))).text;check(py.equals(text(root.resolve("pc/"+row[0]+".py"))),"Identical Python source");String java=FlowJava.generate(source,text(root.resolve("../frociart-v1-capabilities/pc/Source/JavaRuntime.txt")),row[4]).text;check(java.equals(text(root.resolve("pc/"+row[0]+"/"+row[4]+".java"))),"Identical Java source");r.reset();check(r.output.isEmpty()&&r.outputNewlines.isEmpty()&&r.outputText().isEmpty(),"Reset");}
  Document imported=FlowgorithmImport.decode(text(root.resolve("import-fixtures/accepted-no-newline.fprg")));FlowEngine.Runner runner=run(imported,new String[0]);check(runner.outputText().equals("1")&&!runner.outputNewlines.get(0),"Imported false flag");Document spec=FlowPseudocode.decode("DICHIARA continua: INTERO\ncontinua=2\nSTAMPA_CONTINUA continua");for(Node n:spec.nodes)if(n.kind==OUTPUT){Map<String,String> names=new HashMap<>();names.put("continua","valore");check(FlowDeclaration.rewriteNode(n,n.text,names).equals("continua: valore"),"Rename protects prefix");}
  FlowEngine.Runner waiting=new FlowEngine.Runner(FlowPseudocode.decode("DICHIARA n: INTERO\nSTAMPA_CONTINUA \"X\"\nLEGGI n\nSTAMPA_CONTINUA n"));while(waiting.state!=FlowEngine.State.WAITING)waiting.step();check(waiting.outputText().equals("X"),"Partial output before input");check(!waiting.submitInput("abc")&&waiting.state==FlowEngine.State.WAITING&&waiting.output.size()==1,"Invalid input keeps partial line");waiting.submitInput("7");while(waiting.state!=FlowEngine.State.COMPLETED&&waiting.state!=FlowEngine.State.ERROR)waiting.step();check(waiting.outputText().equals("X7"),"Resume same line");
  char[] chars=new char[8000];Arrays.fill(chars,'x');FlowEngine.Runner limit=new FlowEngine.Runner(FlowPseudocode.decode("s=\""+new String(chars)+"\"\nPER i DA 1 A 40 FAI\nSTAMPA_CONTINUA s\nFINE PER"));for(int i=0;i<10000&&limit.state!=FlowEngine.State.COMPLETED&&limit.state!=FlowEngine.State.ERROR;i++)limit.step();check(limit.state==FlowEngine.State.ERROR&&limit.output.size()==32&&limit.outputText().length()==256000,"Quota keeps prior output atomically");FlowEngine.Runner many=run(FlowPseudocode.decode("PER i DA 1 A 2000 FAI\nSTAMPA_CONTINUA \"x\"\nFINE PER"),new String[0]);check(many.output.size()==2000&&many.outputText().length()==2000,"Two thousand fragments");System.out.println("CONTINUATION_ANDROID_CORE PASS checks="+checks);
 }
}
